        topic_ids: vec![1, 2, 3, 4, 5, 6],
        ..Default::default()
    };
    assert!(!query.is_bulk_topic_request());

    let query = ScoredPostsQuery {
        topic_ids: vec![1, 2, 3, 4, 5, 6, 7],
        ..Default::default()
